// Setup oculto: publica 3 bloques que empiezan en ~2 horas y reserva 2 sesiones
// (una se reprograma y cancela en los escenarios alternativos; la otra queda en la agenda).
(async () => {
  const now = new Date();
  let start = new Date(now.getFullYear(), now.getMonth(), now.getDate(),
    now.getHours(), now.getMinutes() + 120 + (parseInt(V("runId"), 10) % 50), 0, 0);
  // Si los bloques cruzarian la medianoche, empiezan a las 00:00 del dia siguiente (sigue siendo <24h)
  if (new Date(start.getTime() + 3 * 3600 * 1000).getDate() !== start.getDate()) {
    start = new Date(start.getFullYear(), start.getMonth(), start.getDate() + 1, 0, 0, 0, 0);
  }
  S("soonDate", dstr(start));
  S("soonStart", pad(start.getHours()) + ":" + pad(start.getMinutes()));
  const end = new Date(start.getTime() + 3 * 3600 * 1000);
  const slots = await send("POST", "/physiotherapists/me/slots", {
    date: dstr(start), startTime: pad(start.getHours()) + ":" + pad(start.getMinutes()),
    endTime: pad(end.getHours()) + ":" + pad(end.getMinutes()), durationMinutes: 60 }, V("physioToken"));
  S("slotSoon1", slots[0].id);
  S("slotSoon2", slots[1].id);
  S("slotSoon3", slots[2].id);
  const b = await send("POST", "/treatment-plans/" + V("planId") + "/sessions", { slotId: slots[0].id }, V("patientToken"));
  S("sessionBId", b.id);
  const c = await send("POST", "/treatment-plans/" + V("planId") + "/sessions", { slotId: slots[2].id }, V("patientToken"));
  S("sessionCId", c.id);
})().catch(e => console.error("setup sesiones <24h:", e));

